{"cards": [{"node_code": "N_dac6529b525ed0ef", "definition": "指桥涵工程立项前的社会经济调查、交通量预测、投资估算及技术方案比选，旨在论证项目建设的必要性、经济合理性与技术可行性。", "boundary": "本节点聚焦于“决策论证”阶段。边界在于区分“经济可行性”与“技术设计”（技术细节归桥涵设计）、“地质水文”（自然条件归相应勘测节点）。若内容涉及施工期成本控制或运营期财务分析，通常归入工程管理或经济类，本节点侧重建设前的宏观论证。", "includes": ["桥涵项目交通需求预测与社会经济影响分析", "工程投资估算、资金筹措方案及财务评价", "多方案技术经济比较与可行性研究编制规范"], "excludes": ["桥涵结构具体设计计算与图纸绘制", "工程地质钻探与水文实测数据获取", "施工过程中的成本管理与运营期维护费用核算"], "sibling_distinctions": [{"other_code": "N_681b38a4f418f379", "rule": "本节点侧重宏观经济论证与决策；地质勘探节点侧重微观自然条件调查与岩土参数获取。"}, {"other_code": "N_b87448734b4b97ff", "rule": "本节点侧重方案比选与立项依据；桥涵设计节点侧重确定方案后的具体结构设计与计算。"}], "cross_boundary_rule": "若内容涉及基于地质条件的方案比选，侧重经济对比归本节点，侧重地质约束分析归地质勘探节点。"}, {"node_code": "N_681b38a4f418f379", "definition": "指为桥涵设计提供依据的工程地质调查，包括地形地貌、地层岩性、地质构造、不良地质现象的勘探，以及岩土物理力学性质试验与评价。", "boundary": "本节点聚焦于“岩土工程条件”的查明。边界在于区分“地质勘探”与“水文勘测”（水文侧重水流与水位，地质侧重岩土体）、“地质勘探”与“结构设计”（设计利用地质参数，勘探获取参数）。若内容涉及通用地质理论，归入地质学，本节点侧重工程应用。", "includes": ["桥位区工程地质测绘、钻探、物探及原位测试", "岩土物理力学性质试验、地基承载力评价", "不良地质现象（如滑坡、岩溶）调查与处理建议"], "excludes": ["河流流量、水位、流速等水文要素勘测与计算", "桥涵结构受力分析与设计计算", "纯基础地质学理论或区域地质背景研究"], "sibling_distinctions": [{"other_code": "N_e9c9ce6be5fd90f6", "rule": "本节点侧重岩土体性质与地质构造；水文勘测节点侧重水体运动规律与水位变化。"}, {"other_code": "N_b87448734b4b97ff", "rule": "本节点侧重获取设计所需的地质基础数据；桥涵设计节点侧重利用数据进行结构选型与计算。"}], "cross_boundary_rule": "若内容涉及地下水对岩土稳定性的影响，侧重水文特征归水文节点，侧重岩土稳定性分析归本节点。"}, {"node_code": "N_e9c9ce6be5fd90f6", "definition": "指桥涵工程所需的水文要素调查与计算，包括河流流量、水位、流速、泥沙、冰凌等观测，以及设计洪水、冲刷深度等水文参数的推算。", "boundary": "本节点聚焦于“水体特征”的查明与计算。边界在于区分“水文勘测”与“地质勘探”（地质侧重岩土，水文侧重水流）、“水文计算”与“结构计算”（结构侧重受力，水文侧重荷载来源）。若内容涉及水利枢纽工程，归入水利工程，本节点侧重桥涵基础水文数据。", "includes": ["桥位区水文站网调查、水位流量关系分析", "设计洪水频率计算、河床演变与冲刷深度预测", "冰凌、泥沙、波浪等对桥涵影响的水文参数计算"], "excludes": ["桥位区岩土工程地质勘探与试验", "桥涵结构抗冲刷设计或基础设计", "通用水文学理论或大型水利枢纽规划"], "sibling_distinctions": [{"other_code": "N_681b38a4f418f379", "rule": "本节点侧重水流与水位等水文要素；地质勘探节点侧重河床及两岸岩土体性质。"}, {"other_code": "N_b87448734b4b97ff", "rule": "本节点侧重提供设计洪水等水文荷载参数；桥涵设计节点侧重利用这些参数进行结构安全验算。"}], "cross_boundary_rule": "若内容涉及水文地质（地下水），侧重地表水流归本节点，侧重地下水与岩土相互作用归地质勘探节点。"}]}
